class Solution {
public:
    std::string smallestBeautifulString(std::string s, int k) {
        int n = s.size();
        int i = n - 1;
        s[i]++;
        while (i < n) {
            if (s[i] == 'a' + k) {
                if (i == 0) return "";
                s[i] = 'a';
                i--;
                s[i]++;
            } else if ((i > 0 && s[i] == s[i - 1]) || (i > 1 && s[i] == s[i - 2])) {
                s[i]++;
            } else {
                i++;
            }
        }
        return s;
    }
};

