var smallestBeautifulString = function(s, k) {
    const a = s.split('').map(c => c.charCodeAt(0) - 97);
    const n = a.length;
    let i = n - 1;
    a[i]++;
    while (i < n) {
        if (a[i] === k) {
            if (i === 0) return '';
            a[i] = 0;
            i--;
            a[i]++;
        } else if ((i > 0 && a[i] === a[i - 1]) || (i > 1 && a[i] === a[i - 2])) {
            a[i]++;
        } else {
            i++;
        }
    }
    return a.map(v => String.fromCharCode(97 + v)).join('');
};
